import fs from 'node:fs';
import {createRequire} from 'node:module';
import {createHash} from 'node:crypto';
import {readLive,verifyDeployedSources} from '../enclave/scripts/network/verify-deployed-sources.mjs';
import {rpcClients,parseProfile} from '../enclave/network/authority-profile.mjs';
const require=createRequire(new URL('../enclave/package.json',import.meta.url));
const file=new URL('./official-soljson.js',import.meta.url);
const hash=createHash('sha256').update(fs.readFileSync(file)).digest('hex');
if(hash!=='ecabf2b0bf0c3ab0c6bb9cebd309900bd3b5e80c833d2bc68a330fa5508398f5')throw Error('official compiler checksum differs');
const solc=require('solc/wrapper')(require(file.pathname));
if(solc.version()!=='0.8.35+commit.47b9dedd.Emscripten.clang')throw Error('wrong compiler version');
const manifest=JSON.parse(fs.readFileSync(new URL('../enclave/contracts/deployments/source-verification-base.json',import.meta.url)));
const {profile}=parseProfile(fs.readFileSync(new URL('../enclave/contracts/deployments/network-profile-base.json',import.meta.url)),{expectedDigest:'sha256:ee957827032cf7208434e4c73f9e859a27e4fc5c6cab5f4a2153308c09eb4cb8'});
const urls=['https://base-rpc.publicnode.com','https://mainnet.base.org','https://base.drpc.org'];
const live=await readLive(manifest,rpcClients(urls));
const result=await verifyDeployedSources({manifest,gitDirs:['/home/steven/Projects/enclave/.git'],live,solc,profile});
const report={checkedAt:new Date().toISOString(),officialCompiler:{source:'https://raw.githubusercontent.com/ethereum/solc-bin/gh-pages/bin/soljson-v0.8.35+commit.47b9dedd.js',sha256:hash,version:solc.version()},blockNumber:String(live.blockNumber),blockHash:live.hash,peerFailures:live.failures,...result};
fs.writeFileSync(new URL('../source-official-compiler-verification.json',import.meta.url),JSON.stringify(report,null,2)+'\n',{flag:'wx'});
console.log(JSON.stringify({ok:result.ok,blockNumber:report.blockNumber,statuses:Object.fromEntries(Object.entries(result.results).map(([k,v])=>[k,v.status]))}));
if(!result.ok)process.exitCode=1;
